const message = ($json.body.message || '').toLowerCase();
let reply = '';
let chips = [];

if (message.includes('react') || message.includes('typescript') || message.includes('review')) {
  reply = '### 💡 Rekomendasi Code Review & Best Practice\n\n1. **Type Safety**: Hindari penggunaan `any`, manfaatkan discriminated unions dan type guards.\n2. **Component Separation**: Pisahkan stateful container dari presentational UI components.\n3. **Memoization**: Gunakan `useMemo`/`useCallback` secara selektif pada kalkulasi berat atau dependency referensial.\n\nApakah kamu ingin meninjau snippet kode tertentu atau optimasi rendering?';
  chips = ['Beri contoh snippet refactoring', 'Bagaimana optimasi re-render?', 'Best practice custom hooks'];
} else if (message.includes('arsitektur') || message.includes('rest') || message.includes('system')) {
  reply = '### 🏗️ Panduan Desain Arsitektur Modern\n\n- **Clean Architecture / Hexagonal**: Pisahkan domain logic dari framework & database driver.\n- **Idempotency**: Selalu rancang POST webhook / payment APIs dengan idempotency key.\n- **Observability**: Lengkapi logging terstruktur dengan Correlation / Trace ID di tiap layer.';
  chips = ['Detail implementasi Idempotency', 'Rekomendasi Caching Redis', 'Contoh Clean Architecture TS'];
} else {
  reply = `### 💻 Mentor Feedback\n\nTopik yang kamu ajukan: \"${$json.body.message}\".\n\nMari kita bedah solusi terbaik dari segi **Maintainability**, **Scalability**, dan **Clean Code Principles**. Apa kendala teknis spesifik yang kamu temui?`;
  chips = ['Review kompleksitas algoritma (Big-O)', 'Tips unit testing dengan Vitest', 'Strategi error handling elegan'];
}

return { json: { content: reply, chips: chips } };
